/**
 * Terms and conditions.
 *
 * ⚠️ The repository holds no terms document, so this one is WRITTEN HERE and carries a visible
 * "pending legal review" notice: the brief asked for structure, not for invented legal certainty.
 * The privacy policy is the opposite case — it already exists, is linked from inside the app, and
 * is guarded by `PrivacyPolicyParityGuardrailTest`, so it is never regenerated by this build.
 */
import { esc, reveal, icon } from '../lib/components.mjs';
import { page } from '../lib/layout.mjs';
import { routes, ORIGIN } from '../lib/config.mjs';

export default function terms({ t, lang, base }) {
  const r = routes(base);

  const body = `<article class="doc">
  <div class="shell shell--narrow">
    <header class="doc__head" ${reveal()}>
      <p class="eyebrow">${esc(t.legalNav.terms)}</p>
      <h1 class="doc__title">${esc(t.terms.h1)}</h1>
      <p class="doc__meta">${esc(t.terms.updated)}</p>
    </header>

    <aside class="callout callout--warn" ${reveal(60)}>
      <span class="icon-tile icon-tile--quiet">${icon('shield', { size: 20 })}</span>
      <div>
        <h2 class="callout__title">${esc(t.terms.draftNotice.title)}</h2>
        <p>${esc(t.terms.draftNotice.body)}</p>
      </div>
    </aside>

    <div class="doc__blocks">
      ${t.terms.sections
        .map(
          (section) => `<section class="doc__block" ${reveal()}>
        <h2 class="doc__h2">${esc(section.h)}</h2>
        ${section.p.map((p) => `<p>${esc(p)}</p>`).join('')}
      </section>`,
        )
        .join('')}
    </div>

    <nav class="doc__foot" aria-label="${esc(t.legalNav.terms)}">
      <a class="link" href="${r.privacy}">${esc(t.legalNav.privacy)}${icon('chevronRight', { size: 16 })}</a>
      <a class="link link--quiet" href="${r.delete}">${esc(t.legalNav.delete)}</a>
    </nav>
  </div>
</article>`;

  return page({
    t,
    lang,
    base,
    pageKey: 'terms',
    title: t.terms.title,
    description: t.terms.description,
    body,
    jsonLd: [
      {
        '@context': 'https://schema.org',
        '@type': 'WebPage',
        name: t.terms.h1,
        url: `${ORIGIN}${r.terms}`,
        inLanguage: t.lang,
      },
    ],
  });
}
